.pricing-upload {display:grid;grid-template-columns:1fr 1fr;gap:16px}
.pricing-upload-file,.pricing-upload-action {grid-column:1/-1}
.pricing-review-layout {display:grid;grid-template-columns:minmax(190px,25%) minmax(0,1fr)}
.pricing-history {padding:17px 14px;background:var(--soft);border-right:1px solid var(--border);min-width:0}
.pricing-history input {font-size:12px}
