function pageLabel(prefix,offset,count,total){$(prefix+'-page').textContent=total?(offset+1)+'–'+(offset+count)+' of '+total:'No records';$(prefix+'-previous').disabled=offset===0;$(prefix+'-next').disabled=offset+count>=total;}
